class Solution { fun alphabetBoardPath(target:String):String{val path=StringBuilder();var row=0;var column=0;for(ch in target){val index=ch-'a';val nextRow=index/5;val nextColumn=index%5;while(row>nextRow){path.append('U');row--};while(column>nextColumn){path.append('L');column--};while(row<nextRow){path.append('D');row++};while(column<nextColumn){path.append('R');column++};path.append('!')};return path.toString()} }
